insert into public.activity_steps (activity_id, position, text, seconds, animation) values
  ('stretch-cuello-hombros', 1, 'Siéntate con la espalda apoyada y los pies en el suelo. Deja caer los hombros.', 30, 'still'),
  ('stretch-cuello-hombros', 2, 'Respira hondo un par de veces y nota cómo está tu cuello ahora mismo.', 60, 'breath:4-6'),
  ('stretch-cuello-hombros', 3, 'Inclina despacio la oreja derecha hacia el hombro derecho. Sin forzar.', 45, 'move'),
  ('stretch-cuello-hombros', 4, 'Vuelve al centro y repite hacia el lado izquierdo.', 45, 'move'),
  ('stretch-cuello-hombros', 5, 'Lleva la barbilla suavemente hacia el pecho y nota la nuca.', 40, 'move'),
  ('stretch-cuello-hombros', 6, 'Gira la cabeza a la derecha, como mirando por encima del hombro. Vuelve y gira a la izquierda.', 60, 'move'),
  ('stretch-cuello-hombros', 7, 'Sube los hombros hacia las orejas, mantén un instante y suéltalos de golpe. Repite varias veces.', 50, 'move'),
  ('stretch-cuello-hombros', 8, 'Haz círculos amplios con los hombros hacia atrás.', 45, 'move'),
  ('stretch-cuello-hombros', 9, 'Ahora círculos hacia delante, despacio.', 45, 'move'),
  ('stretch-cuello-hombros', 10, 'Entrelaza las manos detrás de la cabeza y abre los codos. Respira en esta postura.', 45, 'breath:4-6'),
  ('stretch-cuello-hombros', 11, 'Lleva la mano derecha al hombro izquierdo y estira suavemente el brazo cruzado. Cambia de lado a mitad.', 60, 'move'),
  ('stretch-cuello-hombros', 12, 'Quédate quieto unos segundos y nota la diferencia en cuello y hombros.', 75, 'still'),
  ('stretch-espalda-manos', 1, 'Siéntate en el borde de la silla, con los pies bien apoyados.', 30, 'still'),
