  ('stretch-espalda-manos', 3, 'Gira el tronco hacia la derecha apoyando la mano en el respaldo. Mantén y respira.', 45, 'breath:4-6'),
  ('stretch-espalda-manos', 4, 'Repite el giro hacia la izquierda.', 45, 'breath:4-6'),
